(function(E){ const x = E["exam-09"] = E["exam-09"] || {units:{}}; (x.units = x.units || {})["x09-w2"] = {"id":"x09-w2","patterns":["W2-discuss","W2T-work","TR-halfquestion"],"title":{"en":"Writing Task 2","tr":"Writing Task 2","fa":"Writing Task 2 (نوشتن، تکلیف ۲)"},"objective":{"en":"In this lesson you will learn to write an essay that discusses two opposing views: explain each one fairly in its own paragraph, give your own opinion clearly, and support everything with reasons and examples, in at least 250 words.","tr":"Bu derste iki karşıt görüşü tartışan bir yazı yazmayı öğreneceksin: her birini kendi paragrafında adil biçimde açıklayacak, kendi görüşünü açıkça verecek ve her şeyi nedenler ve örneklerle destekleyeceksin; en az 250 kelimeyle.","fa":"در این درس یاد می‌گیری مقاله‌ای بنویسی که دو دیدگاه مخالف را بررسی می‌کند: هرکدام را منصفانه در پاراگراف خودش توضیح بدهی، نظر خودت را روشن بگویی و همه‌چیز را با دلیل و مثال پشتیبانی کنی، در دست‌کم ۲۵۰ کلمه."},"sessions":[["explain"],["writing"],["exit"]],"explain":{"title":{"en":"Writing Task 2: discuss both views","tr":"Writing Task 2: iki görüşü tartış","fa":"Writing Task 2: بررسی دو دیدگاه"},"objective":{"en":"In this lesson you will learn to write an essay that discusses two opposing views: explain each one fairly in its own paragraph, give your own opinion clearly, and support everything with reasons and examples, in at least 250 words.","tr":"Bu derste iki karşıt görüşü tartışan bir yazı yazmayı öğreneceksin: her birini kendi paragrafında adil biçimde açıklayacak, kendi görüşünü açıkça verecek ve her şeyi nedenler ve örneklerle destekleyeceksin; en az 250 kelimeyle.","fa":"در این درس یاد می‌گیری مقاله‌ای بنویسی که دو دیدگاه مخالف را بررسی می‌کند: هرکدام را منصفانه در پاراگراف خودش توضیح بدهی، نظر خودت را روشن بگویی و همه‌چیز را با دلیل و مثال پشتیبانی کنی، در دست‌کم ۲۵۰ کلمه."},"stats":[{"label":{"en":"Words","tr":"Kelime","fa":"کلمه"},"value":"250+"},{"label":{"en":"Time","tr":"Süre","fa":"زمان"},"value":{"en":"40 min","tr":"40 dk","fa":"۴۰ دقیقه"}},{"label":{"en":"Paragraphs","tr":"Paragraf","fa":"پاراگراف"},"value":"4-5"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: competition or teamwork at work","tr":"Bu sınav: işte rekabet mi takım çalışması mı","fa":"این آزمون: رقابت یا کار گروهی در محیط کار"},"intro":{"en":"\"Discuss both these views and give your own opinion\" is the second most common Task 2 question. Work and careers are one of the most frequent themes, and you can use examples from any job you know.","tr":"\"Discuss both these views and give your own opinion\" en sık çıkan ikinci Task 2 sorusudur. İş ve kariyer en sık görülen temalardan biridir ve bildiğin herhangi bir işten örnek verebilirsin.","fa":"«Discuss both these views and give your own opinion» دومین سؤال رایج Task 2 است. کار و شغل یکی از پرتکرارترین موضوع‌هاست و می‌توانی از هر شغلی که می‌شناسی مثال بزنی."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x09-w2-ctx","exam":true,"patterns":["W2-discuss","W2T-work"],"often":{"pattern":"W2-discuss","n":17,"of":76,"label":{"en":"Comes up often in the real exam: 17 of the last 76 Task 2 questions","tr":"Gerçek sınavda sık çıkar: son 76 Task 2 sorusunun 17’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۷ سؤال از ۷۶ سؤالِ اخیرِ Task 2"}},"title":{"en":"Discuss two views and give your own","tr":"İki görüşü tartış ve kendi görüşünü ver","fa":"دو دیدگاه را بررسی کن و نظر خودت را بگو"},"asks":{"en":"The question gives two opposite opinions. You must explain both fairly, each in its own paragraph, and also say clearly which you agree with, or how far. Leaving out either view, or your own opinion, answers only part of the question.","tr":"Soru iki zıt görüş veriyor. İkisini de adil biçimde, her birini kendi paragrafında açıklamalı ve hangisine ya da ne ölçüde katıldığını açıkça söylemelisin. Görüşlerden birini ya da kendi fikrini atlamak sorunun yalnızca bir kısmını cevaplamaktır.","fa":"سؤال دو نظر مخالف را می‌دهد. باید هر دو را منصفانه، هرکدام در پاراگراف خودش، توضیح بدهی و روشن بگویی با کدام موافقی یا تا چه حد. جا انداختن یکی از دیدگاه‌ها یا نظر خودت یعنی فقط بخشی از سؤال را جواب داده‌ای."},"fields":["Both views in your own words","Your opinion","View 1 explained","View 2 explained","Conclusion"],"words":[{"a":"competition","b":"rivalry / trying to do better than others","tr":"rekabet","fa":"رقابت"},{"a":"teamwork","b":"cooperation / working together","tr":"takım çalışması","fa":"کار گروهی"},{"a":"colleagues","b":"co-workers / the people you work with","tr":"iş arkadaşları","fa":"همکارها"},{"a":"motivate","b":"push people to work harder","tr":"motive etmek","fa":"انگیزه دادن"},{"a":"results","b":"performance / output / targets met","tr":"sonuçlar","fa":"نتیجه‌ها"},{"a":"share knowledge","b":"help each other / pass on skills","tr":"bilgi paylaşmak","fa":"دانش را به اشتراک گذاشتن"},{"a":"some people think","b":"it is argued that / supporters claim","tr":"bazıları düşünüyor","fa":"بعضی‌ها فکر می‌کنند"},{"a":"others believe","b":"on the other hand, critics say","tr":"diğerleri inanıyor","fa":"دیگران معتقدند"},{"a":"in my opinion","b":"I would argue / my own view is","tr":"bence","fa":"به نظر من"},{"a":"a balance","b":"a combination of both / the right mix","tr":"bir denge","fa":"تعادل"},{"a":"reward","b":"bonus / prize / recognition","tr":"ödül","fa":"پاداش"},{"a":"harm","b":"damage / make worse","tr":"zarar vermek","fa":"آسیب زدن"}],"traps":[{"en":"Explaining both views but never giving your own: \"Discuss both these views and give your own opinion\" has three parts.","tr":"İki görüşü açıklayıp kendi görüşünü hiç vermemek: \"Discuss both these views and give your own opinion\" üç parçadan oluşur.","fa":"توضیح هر دو دیدگاه بدون گفتن نظر خودت: «Discuss both these views and give your own opinion» سه بخش دارد."},{"en":"Mixing both views in every paragraph. Give each view its own paragraph, then show where you stand.","tr":"Her paragrafta iki görüşü karıştırmak. Her görüşe kendi paragrafını ver, sonra nerede durduğunu göster.","fa":"قاطی کردن هر دو دیدگاه در همه‌ی پاراگراف‌ها. به هر دیدگاه پاراگراف خودش را بده و بعد نشان بده خودت کجا ایستاده‌ای."}],"example":{"text":"Question: \"Some say children should learn at home; others say school is better. Discuss both views and give your opinion.\"","item":"Which introduction is complete? (a) \"There are two views about this.\" (b) \"While home learning offers flexibility, I believe school is better for most children because of the social skills it develops.\"","answer":"(b)","why":{"en":"(b) mentions both views and gives the writer’s position; (a) gives no opinion.","tr":"(b) iki görüşe de değiniyor ve yazarın tutumunu veriyor; (a) görüş vermiyor.","fa":"(b) به هر دو دیدگاه اشاره می‌کند و موضع نویسنده را می‌گوید؛ (a) نظری نمی‌دهد."}}},{"id":"W2T-work","ctx":["W2-discuss","W2-advdis","W2T-work"],"title":{"en":"Work and careers","tr":"İş ve kariyer","fa":"کار و مسیر شغلی"},"asks":{"en":"Questions about working life: a shorter working week, taking risks, working for yourself, big or small companies, having two jobs, colleagues, family businesses, moving abroad to work.","tr":"Çalışma hayatı üzerine sorular: daha kısa çalışma haftası, risk almak, kendi işini yapmak, büyük ya da küçük şirketler, iki işte çalışmak, iş arkadaşları, aile şirketleri, çalışmak için yurt dışına gitmek.","fa":"سؤال‌هایی درباره‌ی زندگی کاری: هفته‌ی کاری کوتاه‌تر، ریسک کردن، کار برای خود، شرکت بزرگ یا کوچک، دو شغل داشتن، همکاران، کسب‌وکار خانوادگی، مهاجرت برای کار."},"fields":["Is it better to work for a large or a small company?","Do the advantages of self-employment outweigh the disadvantages?","Should colleagues socialise outside work? Discuss both views.","A four-day working week: advantages and disadvantages?","Should skilled workers stay in their own country?"],"words":[{"a":"job","b":"employment / a career","tr":"iş, istihdam","fa":"شغل"},{"a":"boss","b":"employer / manager","tr":"işveren","fa":"کارفرما"},{"a":"workers","b":"employees / staff","tr":"çalışanlar","fa":"کارکنان"},{"a":"money","b":"salary / income / earnings","tr":"maaş, gelir","fa":"حقوق، درآمد"},{"a":"work for yourself","b":"be self-employed / run your own business","tr":"kendi işini yapmak","fa":"برای خود کار کردن"},{"a":"safe job","b":"job security","tr":"iş güvencesi","fa":"امنیت شغلی"},{"a":"move up","b":"promotion / career progression","tr":"terfi, kariyerde ilerleme","fa":"پیشرفت شغلی"},{"a":"balance","b":"work-life balance","tr":"iş-yaşam dengesi","fa":"تعادل کار و زندگی"},{"a":"too much work","b":"heavy workload / long hours","tr":"ağır iş yükü","fa":"حجم کار زیاد"},{"a":"happy at work","b":"job satisfaction","tr":"iş tatmini","fa":"رضایت شغلی"},{"a":"working together","b":"teamwork / collaboration","tr":"ekip çalışması","fa":"کار گروهی"},{"a":"skilled people leave","b":"brain drain","tr":"beyin göçü","fa":"فرار مغزها"}],"traps":[{"en":"\"Do the advantages outweigh the disadvantages?\" needs a clear answer: yes, they do, or no, they do not. Do not just list both.","tr":"\"Avantajlar dezavantajlardan ağır basıyor mu?\" sorusu net bir cevap ister: evet ya da hayır. İkisini sıralamakla yetinme.","fa":"«آیا مزیت‌ها بر معایب می‌چربند؟» جواب روشن می‌خواهد: بله یا نه. فقط هر دو را فهرست نکن."},{"en":"Keep to the question’s group: \"skilled professionals\" is not \"all workers\".","tr":"Sorunun hedef grubunda kal: \"nitelikli profesyoneller\" \"bütün çalışanlar\" değildir.","fa":"در گروه سؤال بمان: «متخصصان ماهر» با «همه‌ی کارگرها» یکی نیست."}],"example":{"text":"Question: More and more people are choosing to work for themselves rather than for an employer. Do the advantages of this outweigh the disadvantages?","item":"Write a thesis sentence.","answer":"In my view, the freedom and flexibility of self-employment outweigh its drawbacks, provided that people plan carefully for an irregular income.","why":{"en":"It answers the exact question (\"outweigh\") with one position and a condition.","tr":"Tam soruya (\"outweigh\") tek bir tutum ve bir koşulla cevap veriyor.","fa":"دقیقاً به سؤال («outweigh») با یک موضع و یک شرط جواب می‌دهد."}},"ideas":["+ Large companies offer training and job security.","- In large companies, individuals can feel invisible.","+ Self-employment gives freedom and flexible hours.","- Income is irregular, with no sick pay.","+ A four-day week can raise productivity and well-being.","- Some services, such as hospitals, cannot easily reduce hours."],"general":true,"patterns":["W2-discuss","W2-advdis","W2T-work"],"often":{"pattern":"W2T-work","n":12,"of":76,"label":{"en":"Comes up often in the real exam: 12 of the last 76 Task 2 questions","tr":"Gerçek sınavda sık çıkar: son 76 Task 2 sorusunun 12’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۲ سؤال از ۷۶ سؤالِ اخیرِ Task 2"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Two views, one opinion","tr":"İki görüş, tek fikir","fa":"دو دیدگاه، یک نظر"},"body":{"en":"Write at least 250 words in about 40 minutes. A clear plan: introduction (both views + your opinion), one paragraph for view 1, one for view 2, and a conclusion that repeats your opinion. Your view can also appear inside the body.","tr":"Yaklaşık 40 dakikada en az 250 kelime yaz. Net bir plan: giriş (iki görüş + senin fikrin), 1. görüş için bir paragraf, 2. görüş için bir paragraf ve fikrini tekrarlayan bir sonuç. Görüşün gövdede de görünebilir.","fa":"در حدود ۴۰ دقیقه دست‌کم ۲۵۰ کلمه بنویس. یک برنامه‌ی روشن: مقدمه (هر دو دیدگاه + نظر تو)، یک پاراگراف برای دیدگاه ۱، یکی برای دیدگاه ۲، و نتیجه‌ای که نظرت را تکرار می‌کند. نظرت می‌تواند در بدنه هم بیاید."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Plan in four steps","tr":"Dört adımda plan","fa":"برنامه‌ریزی در چهار قدم"},"steps":[{"en":"Rewrite each view in your own words before you plan.","tr":"Plan yapmadan önce her görüşü kendi kelimelerinle yeniden yaz.","fa":"قبل از برنامه‌ریزی هر دیدگاه را با کلمه‌های خودت بازنویسی کن."},{"en":"Find one strong reason and one example for each view.","tr":"Her görüş için güçlü bir neden ve bir örnek bul.","fa":"برای هر دیدگاه یک دلیل قوی و یک مثال پیدا کن."},{"en":"Decide your opinion: one side, or a balance with a clear reason.","tr":"Görüşüne karar ver: bir taraf ya da net bir nedene dayanan bir denge.","fa":"نظرت را مشخص کن: یک طرف، یا تعادلی با دلیل روشن."},{"en":"Put the view you agree with second, so the essay leads naturally to your conclusion.","tr":"Katıldığın görüşü ikinci sıraya koy; böylece yazı doğal olarak sonucuna varır.","fa":"دیدگاهی را که با آن موافقی دوم بیاور تا مقاله به‌طور طبیعی به نتیجه‌ات برسد."}]},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Reporting views, then your own","tr":"Görüşleri aktarmak, sonra kendininkini","fa":"نقل دیدگاه‌ها، بعد نظر خودت"},"table":{"headers":{"en":["Purpose","Phrase"],"tr":["Amaç","İfade"],"fa":["هدف","عبارت"]},"rows":[["View 1","Supporters of competition argue that..."],["View 2","Others, however, believe that..."],["Your opinion","In my view, ... because..."],["A balanced position","The best results, I believe, come from a combination of..."]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"A body paragraph, step by step","tr":"Bir gövde paragrafı, adım adım","fa":"یک پاراگراف بدنه، قدم به قدم"},"instruction":"View: \"Some people believe uniforms help students concentrate.\"","item":"Write the topic sentence and a supporting example.","answer":"Supporters of school uniforms argue that they help students to concentrate. When everyone wears the same clothes, there is less pressure to follow fashion, so attention stays on lessons.","walk":[{"en":"Report the view, not your opinion: \"Supporters... argue that\".","tr":"Görüşü aktar, kendi fikrini değil: \"Supporters... argue that\".","fa":"دیدگاه را نقل کن، نه نظر خودت را: «Supporters... argue that»."},{"en":"Explain why someone would think this: less pressure to follow fashion.","tr":"Birinin neden böyle düşündüğünü açıkla: modayı takip etme baskısı azalır.","fa":"توضیح بده چرا کسی این‌طور فکر می‌کند: فشار برای دنبال کردن مد کم می‌شود."},{"en":"Link the reason back to the view: attention stays on lessons.","tr":"Nedeni görüşe geri bağla: dikkat derslerde kalır.","fa":"دلیل را به دیدگاه برگردان: حواس روی درس می‌ماند."}]},"quick":{"prompt":"Which conclusion answers \"Discuss both these views and give your own opinion\"?","options":["There are two different views on this topic.","Both views have merit, but I believe cooperation achieves more in the long run.","Competition and cooperation are both common at work."],"correct":1,"why":{"en":"Only the first gives the writer’s own opinion; the others just describe the views.","tr":"Yalnızca ilki yazarın kendi görüşünü veriyor; diğerleri sadece görüşleri anlatıyor.","fa":"فقط اولی نظر خودِ نویسنده را می‌گوید؛ بقیه فقط دیدگاه‌ها را توصیف می‌کنند."}},"remember":{"en":"Both views fairly, each in its own paragraph, and your own opinion clearly at the start and the end.","tr":"İki görüş de adil, her biri kendi paragrafında; kendi fikrin başta ve sonda açıkça.","fa":"هر دو دیدگاه منصفانه، هرکدام در پاراگراف خودش، و نظر خودت روشن در اول و آخر."},"type":"explain","id":"c-x09-w2-e","course":"ielts-exams","exam":"exam-09","unit":"x09-w2"},"writing":{"taskKind":"exam","title":{"en":"Write the essay: competition or teamwork","tr":"Yazıyı yaz: rekabet mi takım çalışması mı","fa":"مقاله را بنویس: رقابت یا کار گروهی"},"task":"task2","reviewLabel":{"en":"Exam 9 · Writing Task 2 (discuss both views: competition or teamwork between colleagues)"},"timed":40,"minWords":250,"ctx":["W2-discuss","W2T-work"],"prompt":{"en":"You should spend about 40 minutes on this task. Write about the following topic: Some people think that competition between colleagues produces the best results at work. Others believe that working together as a team is more effective. Discuss both these views and give your own opinion. Give reasons for your answer and include any relevant examples from your own knowledge or experience. Write at least 250 words.","tr":"Bu göreve yaklaşık 40 dakika ayırmalısın. Şu konu hakkında yaz: Bazı insanlar iş arkadaşları arasındaki rekabetin işte en iyi sonuçları verdiğini düşünüyor. Diğerleri ise ekip olarak birlikte çalışmanın daha etkili olduğuna inanıyor. Her iki görüşü de tartış ve kendi görüşünü belirt. Cevabını gerekçelendir ve kendi bilgi ya da deneyimlerinden ilgili örnekler ver. En az 250 kelime yaz.","fa":"باید حدود ۴۰ دقیقه برای این تکلیف وقت بگذاری. درباره‌ی این موضوع بنویس: بعضی‌ها فکر می‌کنند رقابت بین همکارها بهترین نتیجه را در کار می‌دهد. دیگران معتقدند کار کردن با هم به‌صورت تیمی مؤثرتر است. هر دو دیدگاه را بررسی کن و نظر خودت را بگو. برای جوابت دلیل بیاور و از دانسته‌ها یا تجربه‌ی خودت مثال‌های مرتبط بزن. دست‌کم ۲۵۰ کلمه بنویس."},"model":"Many employers try to raise performance by making staff compete, for example through sales rankings or bonuses for the best individual results. Others prefer to reward teams rather than individuals. While competition can certainly motivate people, I believe that teamwork usually produces better results in the long run.\n\nSupporters of competition argue that it brings out the best in people. When employees know that their results will be compared with those of their colleagues, many work harder and set themselves higher targets. In sales, for instance, a monthly league table can encourage staff to make extra calls or find new customers, and the most successful employees are easy to identify and reward.\n\nHowever, others believe that cooperation is more effective, and I share this view. Most modern jobs are too complex for one person to do alone, and they depend on people sharing information. If colleagues see each other as rivals, they may keep useful knowledge to themselves or even avoid helping a struggling team member. In a hospital, for example, the quality of care depends far more on doctors and nurses working closely together than on any individual's performance.\n\nTeamwork also tends to create a better atmosphere. Employees who feel supported are less likely to suffer from stress or to leave the company, which saves the cost of recruiting and training new staff. In my own experience of working in a busy restaurant, the shifts went best when the kitchen and the waiters helped each other rather than competing for tips.\n\nIn conclusion, although a degree of competition can push individuals to work harder, I am convinced that cooperation leads to better results overall. The most effective organisations reward shared success while still recognising outstanding individual effort.","moves":[{"label":{"en":"1 Introduction: both views + your opinion","tr":"1 Giriş: iki görüş + senin fikrin","fa":"۱ مقدمه: هر دو دیدگاه + نظر تو"},"text":"While competition can certainly motivate people, I believe that teamwork usually produces better results in the long run."},{"label":{"en":"2 View 1, explained fairly + example","tr":"2 Görüş 1, adil biçimde + örnek","fa":"۲ دیدگاه ۱، منصفانه + مثال"},"text":"Supporters of competition argue that it brings out the best in people... In sales, for instance..."},{"label":{"en":"3 View 2 + your agreement + example","tr":"3 Görüş 2 + katıldığını göstermek + örnek","fa":"۳ دیدگاه ۲ + موافقت تو + مثال"},"text":"However, others believe that cooperation is more effective, and I share this view... In a hospital, for example..."},{"label":{"en":"4 A further reason for your view","tr":"4 Görüşün için ek bir neden","fa":"۴ دلیلی دیگر برای نظرت"},"text":"Teamwork also tends to create a better atmosphere..."},{"label":{"en":"5 Conclusion: the same opinion","tr":"5 Sonuç: aynı görüş","fa":"۵ نتیجه: همان نظر"},"text":"In conclusion, although a degree of competition can push individuals to work harder, I am convinced..."}],"rubric":["Covers the task: both views explained, a clear opinion of your own, ideas supported with reasons and examples.","Organised: introduction, one paragraph per view, conclusion; linking that sounds natural.","Words: topic words used precisely and naturally; the question paraphrased, not copied.","Sentences: a range of sentence types, mostly accurate; articles, agreement and punctuation checked."],"rubricI18n":{"tr":["Görevi karşılıyor: iki görüş açıklanmış, kendine ait net bir görüş var, fikirler nedenler ve örneklerle desteklenmiş.","Düzenli: giriş, her görüş için bir paragraf, sonuç; doğal görünen bağlantılar.","Kelimeler: konu kelimeleri yerinde ve doğal kullanılmış; soru kopyalanmamış, başka sözcüklerle anlatılmış.","Cümleler: çeşitli cümle türleri, çoğunlukla doğru; tanımlıklar, özne-yüklem uyumu ve noktalama kontrol edilmiş."],"fa":["تکلیف را پوشش می‌دهد: هر دو دیدگاه توضیح داده شده، نظر روشنی از خودت هست و ایده‌ها با دلیل و مثال پشتیبانی شده‌اند.","منظم است: مقدمه، یک پاراگراف برای هر دیدگاه، نتیجه‌گیری؛ ربط‌دهنده‌هایی که طبیعی‌اند.","کلمه‌ها: کلمه‌های موضوعی دقیق و طبیعی به کار رفته‌اند؛ سؤال با کلمه‌های دیگر بیان شده، نه کپی.","جمله‌ها: انواع مختلف جمله، بیشترشان درست؛ حرف تعریف، مطابقت فعل و فاعل و نشانه‌گذاری بررسی شده."]},"rubricBands":{"note":{"en":"Score each line from 0 to 3. Read the line for the score you choose: it tells you what to improve next.","tr":"Her satırı 0’dan 3’e puanla. Seçtiğin puanın satırını oku: bir sonraki adımda neyi geliştireceğini söyler.","fa":"به هر خط از ۰ تا ۳ نمره بده. توضیحِ نمره‌ای را که انتخاب می‌کنی بخوان: می‌گوید قدم بعدی چه چیزی را بهتر کنی."},"order":["task","organised","words","sentences"],"task":[{"en":"The question is not really answered; no clear position.","tr":"Soru tam olarak cevaplanmamış; net bir tutum yok.","fa":"در واقع به سؤال جواب داده نشده؛ موضع روشنی نیست."},{"en":"A position, but only part of the question is answered, or ideas are not explained.","tr":"Bir tutum var ama sorunun yalnızca bir kısmı cevaplanmış ya da fikirler açıklanmamış.","fa":"موضعی هست، اما فقط بخشی از سؤال جواب داده شده یا ایده‌ها توضیح داده نشده‌اند."},{"en":"Every part answered, one clear position, main ideas supported.","tr":"Her kısım cevaplanmış, tek ve net bir tutum, ana fikirler desteklenmiş.","fa":"به همه‌ی بخش‌ها جواب داده شده، یک موضع روشن هست و ایده‌های اصلی پشتیبانی شده‌اند."},{"en":"A clear, consistent position; ideas fully explained with relevant examples.","tr":"Net ve tutarlı bir tutum; fikirler yerinde örneklerle tam açıklanmış.","fa":"موضعی روشن و یکدست؛ ایده‌ها با مثال‌های مرتبط کامل توضیح داده شده‌اند."}],"organised":[{"en":"No clear paragraphs.","tr":"Net paragraflar yok.","fa":"پاراگراف‌های روشنی ندارد."},{"en":"Paragraphs, but more than one main idea in each, or forced linking words.","tr":"Paragraflar var ama her birinde birden fazla ana fikir ya da zorlama bağlaçlar.","fa":"پاراگراف دارد، اما در هر کدام بیش از یک ایده‌ی اصلی هست یا کلمه‌های ربط تصنعی‌اند."},{"en":"Introduction, body paragraphs with one idea each, conclusion.","tr":"Giriş, her biri tek fikirli gövde paragrafları, sonuç.","fa":"مقدمه، پاراگراف‌هایی که هر کدام یک ایده دارند، نتیجه."},{"en":"A logical flow from start to end; linking is natural.","tr":"Baştan sona mantıklı bir akış; bağlantılar doğal.","fa":"جریانی منطقی از اول تا آخر؛ ربط‌ها طبیعی‌اند."}],"words":[{"en":"Very basic words; the question is copied.","tr":"Çok temel kelimeler; soru kopyalanmış.","fa":"کلمه‌های خیلی ساده؛ صورت سؤال کپی شده."},{"en":"Topic words repeated; some wrong word choices.","tr":"Konu kelimeleri tekrarlanmış; bazı yanlış kelime seçimleri.","fa":"کلمه‌های موضوع تکرار شده‌اند؛ چند انتخاب کلمه‌ی غلط هست."},{"en":"Topic words used well; the question is said in other words.","tr":"Konu kelimeleri iyi kullanılmış; soru başka sözcüklerle anlatılmış.","fa":"کلمه‌های موضوع خوب به کار رفته‌اند؛ سؤال با کلمه‌های دیگر بیان شده."},{"en":"Precise, natural topic words; almost no errors.","tr":"Yerinde, doğal konu kelimeleri; neredeyse hatasız.","fa":"کلمه‌های موضوعِ دقیق و طبیعی؛ تقریباً بی‌غلط."}],"sentences":[{"en":"Mostly short sentences with frequent errors.","tr":"Çoğunlukla kısa cümleler, sık hatalar.","fa":"بیشتر جمله‌های کوتاه با غلط‌های زیاد."},{"en":"Some longer sentences; errors sometimes make the meaning unclear.","tr":"Bazı uzun cümleler; hatalar bazen anlamı belirsizleştiriyor.","fa":"چند جمله‌ی بلندتر؛ غلط‌ها گاهی معنی را نامفهوم می‌کنند."},{"en":"A mix of sentence types; errors rarely affect the meaning.","tr":"Çeşitli cümle türleri; hatalar anlamı nadiren etkiliyor.","fa":"ترکیبی از انواع جمله؛ غلط‌ها به‌ندرت روی معنی اثر می‌گذارند."},{"en":"A wide range of sentences, almost all accurate.","tr":"Çok çeşitli cümleler, neredeyse hepsi doğru.","fa":"جمله‌های خیلی متنوع، تقریباً همه درست."}]},"type":"writing","id":"c-x09-w2-w","course":"ielts-exams","exam":"exam-09","unit":"x09-w2"},"exit":{"type":"exit","items":[{"tests":"word","point":3,"prompt":"\"Colleagues may see each other as rivals.\" Rivals are people who...","options":["compete against each other","work in the same office","share the same manager"],"correct":0,"why":{"en":"A rival is someone you compete with.","tr":"Rival, rekabet ettiğin kişidir.","fa":"rival کسی است که با او رقابت می‌کنی."}},{"tests":"paraphrase","point":3,"prompt":"Which phrase does NOT copy \"working together as a team\" from the question?","options":["working together as a team","work together as a team","cooperation"],"correct":2,"why":{"en":"\"Cooperation\" expresses the same idea in a new word; the others repeat the question.","tr":"\"Cooperation\" aynı fikri yeni bir kelimeyle anlatıyor; diğerleri soruyu tekrarlıyor.","fa":"«cooperation» همان ایده را با کلمه‌ای تازه می‌گوید؛ بقیه سؤال را تکرار می‌کنند."}},{"tests":"method","point":2,"prompt":"Where is the best place to put the view you agree with?","options":["first, so the reader knows it at once","second, so the essay leads to your conclusion","in the conclusion only"],"correct":1,"why":{"en":"Putting your side second makes the move to your conclusion natural; your opinion is still stated in the introduction.","tr":"Kendi tarafını ikinci sıraya koymak sonuca geçişi doğal kılar; görüşün yine de girişte belirtilir.","fa":"آوردن طرف خودت در جای دوم رسیدن به نتیجه را طبیعی می‌کند؛ نظرت باز هم در مقدمه گفته می‌شود."}},{"tests":"trap","point":1,"prompt":"An essay explains both views well but never says what the writer thinks. What is missing?","options":["the writer’s own opinion","a second example","a longer introduction"],"correct":0,"why":{"en":"\"Give your own opinion\" is part of the question; without it, only part of the task is done.","tr":"\"Kendi görüşünü belirt\" sorunun bir parçası; o olmadan görevin yalnızca bir kısmı yapılmış olur.","fa":"«نظر خودت را بگو» بخشی از سؤال است؛ بدون آن فقط بخشی از تکلیف انجام شده."}}],"id":"c-x09-w2-x","course":"ielts-exams","exam":"exam-09","unit":"x09-w2"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
